  const stage=document.querySelector('#client-service');
  stage.dispatchEvent(new CustomEvent('mercury-cabinet-return',{detail:request.photo}));
  if(lessMotion.matches){finishCabinet();return;}
  const mobile=matchMedia('(max-width:760px)').matches;
