form.addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();if(qStep<4){if(validateStep(qStep)){qStep++;renderStep();}return;}for(let n=0;n<4;n++){if(!validateStep(n)){qStep=n;renderStep();validateStep(n);return;}}const c=value('contact').trim(),digits=c.replace(/\D/g,''),phone=/^[+\d\s()\-]+$/.test(c)&&digits.length>=10&&digits.length<=15,tg=/^@[a-zA-Z][a-zA-Z0-9_]{4,31}$/.test(c);if(value('method')==='phone'?!phone:!(phone||tg)){showError(value('method')==='phone'?'Укажите номер телефона с кодом страны.':'Укажите Telegram в формате @username или номер телефона.',form.elements.contact);return;}deliver(answerRows(false),c,value('method'));});
quiz.addEventListener('close',()=>{if(qComplete){form.elements.contact.value='';form.elements.plan.value='';document.getElementById('q-summary').replaceChildren();}if(quizOrigin?.isConnected)quizOrigin.focus({preventScroll:true});});

const project=document.getElementById('cx-project');
function renderGallery(){const c=CASES[activeCase];document.getElementById('cx-project-image').src=c.images[galleryIndex];document.getElementById('cx-project-image').alt=c.title+' · изображение '+(galleryIndex+1);document.getElementById('cx-gallery-count').textContent=(galleryIndex+1)+' / '+c.images.length;project.querySelector('[data-gallery-prev]').disabled=c.images.length<2;project.querySelector('[data-gallery-next]').disabled=c.images.length<2;}
function openProject(id){activeCase=id;galleryIndex=0;const c=CASES[id];document.getElementById('cx-project-title').textContent=c.title;document.getElementById('cx-project-area').textContent=c.area;document.getElementById('cx-project-type').textContent=c.type;document.getElementById('cx-project-source').href=c.url;renderGallery();project.showModal();project.scrollTop=0;}
window.addEventListener('click',e=>{const jump=e.target.closest('.mb-review-tools a[href^="#"],.cx-hero-links a[href^="#"]');if(jump){const dest=document.getElementById(jump.getAttribute('href').slice(1));if(dest){e.preventDefault();e.stopImmediatePropagation();window.scrollTo({top:dest.getBoundingClientRect().top+scrollY-(dest.id==='rec1207085146'?0:95),behavior:reduceMotion.matches?'auto':'smooth'});return;}}const el=e.target.closest('[data-quiz],[data-q-close],[data-q-next],[data-q-prev],[data-q-edit],[data-stage-select],[data-process-play],[data-mb-demo],[data-mb-note],[data-mb-note-close],[data-close-dialog],[data-project],[data-gallery-next],[data-gallery-prev]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();if(el.hasAttribute('data-quiz'))return openQuiz(el);if(el.hasAttribute('data-q-close'))return quiz.close();if(el.hasAttribute('data-q-next')){if(validateStep(qStep)){qStep++;renderStep();}return;}if(el.hasAttribute('data-q-prev')){qStep=Math.max(0,qStep-1);renderStep();return;}if(el.hasAttribute('data-q-edit')){qStep=0;renderStep();return;}if(el.hasAttribute('data-stage-select')){stopPlay();seekStage(Number(el.dataset.stageSelect));return;}if(el.hasAttribute('data-process-play'))return playProcess();if(el.hasAttribute('data-mb-demo'))return openCabinet(el.dataset.mbDemo||'object',el);if(el.hasAttribute('data-mb-note'))return document.getElementById('mb-note').showModal();if(el.hasAttribute('data-mb-note-close')||el.hasAttribute('data-close-dialog'))return el.closest('dialog').close();if(el.dataset.project)return openProject(el.dataset.project);if(el.hasAttribute('data-gallery-next')||el.hasAttribute('data-gallery-prev')){const len=CASES[activeCase].images.length;galleryIndex=(galleryIndex+(el.hasAttribute('data-gallery-next')?1:-1)+len)%len;renderGallery();}},true);
