// The native Tilda button owns validation, antifraud, delivery and receiver selection.
let uploader, placeholder, busy = false;
const fileLabel = form.querySelector('.q-file');
const button = form.querySelector('[data-q-submit]');
const uploaderSlot = document.createElement('div');
fileLabel.after(uploaderSlot);
fileLabel.hidden = true;
function syncUploader() {
  const active = quiz.open && qStep === 4 && !qComplete;
  if (active && !uploader) {
    const group = document.querySelector('#form1217709971 .t-input-group_uw');
    if (!group) return;
    placeholder = document.createComment('native upload position');
    group.before(placeholder);
    uploader = group;
    uploaderSlot.append(group);
  } else if (!active && uploader && !busy) {
    placeholder.replaceWith(uploader);
    uploader = placeholder = null;
  }
}
new MutationObserver(syncUploader).observe(quiz,{attributes:true,attributeFilter:['open'],subtree:false});
new MutationObserver(syncUploader).observe(form.querySelector('[data-q-step="4"]'),{attributes:true,attributeFilter:['hidden']});
function deliver(rows, contact, method) {
  if (busy) return;
  const original = document.querySelector('#form1217709971');
  const services = original?.querySelectorAll('.js-formaction-services');
  if (!services?.length || typeof window.t_forms__initBtnClick !== 'function') {
    showError('Форма пока не загрузилась. Повторите отправку через несколько секунд.',button);
    return;
  }
  const url = uploader?.querySelector('[name="File"]')?.value;
  if (uploader?.querySelector('input[type=file]')?.files?.length && !url) {
    showError('Дождитесь загрузки планировки или удалите файл.',button);
    return;
  }
  const transport = document.createElement('form');
  transport.hidden = true;
  transport.id = original.id + '_quiz';
  transport.className = 't-form js-form-proccess';
  transport.setAttribute('data-formactiontype','2');
  transport.setAttribute('data-formname','Расчёт проекта Mercury');
  services.forEach(el => transport.append(el.cloneNode(true)));
  function field(name,value) {
    const input = document.createElement('input');
    input.type = 'hidden'; input.name = name; input.value = value;
    transport.append(input);
  }
  field('formname','Расчёт проекта Mercury');
  field(contact.startsWith('@')?'Telegram':'Phone',contact);
  field('Способ связи',method === 'telegram'?'Telegram':'Телефон');
  rows.forEach(([k,v])=>field(k,v));
  if (!document.querySelector('#q-origin').hidden) field('Интерес',document.querySelector('#q-origin').textContent);
  if (url) field('File',url);
  const send = document.createElement('button');
  send.type='submit'; send.className='t-submit';
  transport.append(send);
  const record = original.closest('.r');
  record.append(transport);
  busy = button.disabled = true;
  const cleanup = () => { busy = button.disabled = false; setTimeout(()=>transport.remove(),1000); syncUploader(); };
  transport.addEventListener('tildaform:aftersuccess',()=>{
    renderRows(document.getElementById('q-summary'),[...rows,['Контакт',contact]]);
    document.getElementById('q-active').hidden=true;
    const success=document.getElementById('q-success');
    success.hidden=false;qComplete=true;quiz.scrollTop=0;success.focus();
    if(url && uploader) uploader.querySelector('[name="File"]').value='';
    cleanup();
  },{once:true});
  transport.addEventListener('tildaform:aftererror',()=>{
    const detail = transport.querySelector('.js-rule-error-all')?.textContent?.trim();
    showError(detail || 'Не удалось отправить заявку. Ответы сохранены. Попробуйте ещё раз.',button);
    cleanup();
  },{once:true});
  transport.addEventListener('submit',event=>event.preventDefault());
  // Tilda's delegated handler is already registered on the original record.
  send.click();
}

