  const angles = [3.36,5.70,2.43,.39,4.16,1.27,2.96,5.27,.78,3.68,5.96];
  const sizes = [18,24,13,22,24,17,26,21,15,29,26];

  let seed=8053;
  const random=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296};
